import React, { useState, useMemo, useRef } from "react";

/*  ────────────────────────────────────────────────────────────────
    MURO DE ARRIMO — Verificação estrutural
    Reprodução fiel das fórmulas da planilha "Caludo_de_muros_de_Arrimo.xlsx".
    Cada saída referencia a célula de origem (ex.: J18). Nenhuma fórmula
    foi alterada. A verificação de fundação em estaca foi removida a
    pedido — permanecem geometria, empuxos, momentos, estabilidade e
    tensões no solo.
    ──────────────────────────────────────────────────────────────── */

const SHEET_IMG = "data:image/jpeg;base64,";

const LOGO_INEC = "data:image/png;base64,";
// Vídeo "como usar a calculadora" — cole o URL (YouTube, Vimeo ou .mp4).
// Deixe "" para exibir o espaço reservado do vídeo.
const VIDEO_URL = "https://youtu.be/gJm5VJhEcUA";
const PONTES_URL = "https://inec.com.br/inec-pos-graduacao-v2/?utm_source=calcmuroarrimo";
const PROTENDIDO_URL = "https://inec.com.br/posprotendido-v8/?utm_source=calcmurorrimo";

// ---- Entradas padrão = valores originais da planilha (reproduzem os
//      resultados dígito a dígito ao carregar). --------------------------
const DEFAULTS = {
  h: "5.7",        // D5  Altura útil do muro (m)
  b2: "2.7",       // D8  base interna / talão (m)
  b1: "0.8",       // D9  base externa / pé (m)
  eBase: "0.85",   // D10 espessura da base (m)
  e1Pe: "0.7",     // D11 espessura da parede no pé (m)
  e2Topo: "0.7",   // D12 espessura da parede no topo (m)
  gSolo: "1800",   // D14 peso específico do solo (kgf/m³)
  q: "2500",       // D15 sobrecarga sobre o terreno (kgf/m²)
  maj: "1.1",      // D16 majorador de sobrecarga (-)
  gKa: "600",      // D17 γ·Ka pressão do solo na parede (kgf/m³)
  Tadm: "1",       // N7  tensão admissível do solo (kgf/cm²) — conferência
  phi: "30",       // N8  ângulo de atrito interno (graus)
};

// constantes embutidas nas fórmulas da planilha (fixas)
const GAMMA_C = 2500; // peso específico do concreto (kgf/m³) — J7, J8, N20
const GF = 1.4;       // coef. de majoração γf — cisalhamento N6
const FSOB = 1.36;    // fator de sobrecarga no talão — J10
const COBR = 5;       // desconto (cm) no cisalhamento — N6: (100·D11 − 5)

const num = (s) => {
  const v = parseFloat(String(s).replace(",", "."));
  return Number.isFinite(v) ? v : 0;
};

function compute(I) {
  const D5 = num(I.h), D8 = num(I.b2), D9 = num(I.b1), D10 = num(I.eBase),
        D11 = num(I.e1Pe), D12 = num(I.e2Topo), D14 = num(I.gSolo),
        D15 = num(I.q), D16 = num(I.maj), D17 = num(I.gKa), N7 = num(I.Tadm),
        N8 = num(I.phi);

  // 1. Geometria derivada
  const D6 = D5 + D10;                 // Altura total H
  const D7 = D8 + D9;                  // Base total b
  const D13 = (D12 + D11) / 2;         // Espessura média
  const D18 = D14 ? (D15 * D16) / D14 : 0; // Altura equivalente Dh

  // 5. Volumes e pesos
  const N19 = (D7 + D5) * D13;         // Volume do muro
  const N20 = N19 * GAMMA_C;           // Peso do muro
  const N21 = (D8 - D13) * D5;         // Volume terra sobre base
  const N22 = N21 * D14;               // Peso da terra

  // 2. Empuxos e cargas
  const J5 = D17 * D6;                 // Empuxo solo Eo
  const J6 = D17 * D18;                // Empuxo sobrecarga DE
  const J7 = D13 * D5 * GAMMA_C;       // P1 peso da parede
  const J8 = D10 * D7 * GAMMA_C;       // P2 peso da base
  const J9 = N22;                      // P3 peso terra na base
  const J10 = D15 * (D8 - D13) * FSOB; // P4 sobrecarga
  const J11 = J7 + J8 + J9 + J10;      // Carga total vertical

  // 3. Momentos
  const J15 = (D6 * D6) * (3 * J6 + J5) / 6;         // Momento tombamento
  const J16 = (D5 * D5) * (3 * J6 + (D17 * D5)) / 6; // Mk (momento em e1)
  const J21 = J7 * (D13 / 2 + D9);     // M1
  const J22 = J8 * D7 / 2;             // M2
  const J23 = J9 * (D8 + D13) / 2;     // M3
  const J24 = J10 * ((D8 + D13) / 2 + D9); // M4
  const J17 = J21 + J22 + J23 + J24;   // Momento resistente Mr
  const J18 = J15 ? J17 / J15 : 0;     // Coef. de segurança (tombamento)
  const J27 = J7 * ((D7 - D13) / 2 - D9);   // Mo1
  const J28 = 0;                            // Mo2
  const J29 = -J9 * (D7 - D8 + D13) / 2;    // Mo3
  const J30 = -J10 * (D7 - D8 + D13) / 2;   // Mo4
  const J31 = (J27 + J28 + J29 + J30) + J15; // Mo Total

  // 4. Reações e tensão no solo
  const N5 = J6 * D6 + J5 * D6 / 2;    // Reação horizontal Fh
  const denomCis = (100 * D11 - COBR);
  const N6 = denomCis ? N5 * GF / 100 / denomCis : 0; // Cisalhamento td
  const N11 = D7 ? J11 / 100 / (100 * D7) : 0;        // Tensão média T1
  const N12 = D7 ? J31 * 6 / Math.pow(100 * D7, 2) : 0; // Tensão média T2
  const N9 = N12 + N11;                // Tensão máxima Tmax
  const N10 = N11 - N12;               // Tensão mínima Tmin
  const N13 = Math.tan(N8 * Math.PI / 180) * J11; // Força horiz. resistente Fhr
  const N14 = N5 ? N13 / N5 : 0;       // CS horizontal (deslizamento)
  const N15 = (N9 - N10) ? N9 / (N9 - N10) : 0;   // Área comprimida / base

  return {
    // geometria
    D5, D6, D7, D8, D9, D10, D11, D12, D13, D14, D15, D16, D17, D18, N7, N8,
    // empuxos/cargas
    J5, J6, J7, J8, J9, J10, J11,
    // momentos
    J15, J16, J17, J18, J21, J22, J23, J24, J27, J28, J29, J30, J31,
    // tensões/reações
    N5, N6, N9, N10, N11, N12, N13, N14, N15,
    // volumes
    N19, N20, N21, N22,
    // verdictos da planilha
    CS_ok: J18 > 1.5,        // L18
    CIS_ok: N6 < 6,          // P6
  };
}

/* ---------- formatação pt-BR ---------- */
const f = (n, d = 2) =>
  new Intl.NumberFormat("pt-BR", { minimumFractionDigits: d, maximumFractionDigits: d })
    .format(Number.isFinite(n) ? n : 0);

/* ==================================================================
   DESENHO DA SEÇÃO (assinatura visual) — atualiza com a geometria
   ================================================================== */
function WallSection({ o }) {
  const W = 560, H = 640;
  const mL = 62, mR = 118, mT = 46, mB = 58;   // margens (px)
  const pxPress = 84;                            // largura máx. do diagrama de pressão
  const b = o.D7, Ht = o.D6, e1 = o.D11, e2 = o.D12, eb = o.D10, b1 = o.D9;
  if (!(b > 0 && Ht > 0)) return null;

  const usableW = W - mL - mR - pxPress;
  const usableH = H - mT - mB;
  const s = Math.min(usableW / b, usableH / Ht);
  const offX = mL + (usableW - b * s) / 2;
  const X = (mx) => offX + mx * s;
  const Y = (my) => (H - mB) - my * s;

  const DE = o.J6, Eo = o.J5, pMax = DE + Eo;
  const wPx = (p) => (pMax > 0 ? (p / pMax) * pxPress : 0);
  const xBack = X(b);
  const yBar = o.N5 ? (H - mB) - (o.J15 / o.N5) * s : Y(Ht / 3); // altura da resultante Fh

  // stem faces
  const stemBL = X(b1), stemBRb = X(b1 + e1), stemTRb = X(b1 + e2);
  const yTop = Y(Ht), yBaseTop = Y(eb), yBot = Y(0);

  const dim = "#5A6672";
  const tick = (x1, y1, x2, y2) => <line x1={x1} y1={y1} x2={x2} y2={y2} stroke={dim} strokeWidth="1" />;

  return (
    <svg viewBox={`0 0 ${W} ${H}`} width="100%" style={{ display: "block" }}>
      <defs>
        <pattern id="soil" width="9" height="9" patternTransform="rotate(45)" patternUnits="userSpaceOnUse">
          <rect width="9" height="9" fill="var(--soil-soft)" />
          <line x1="0" y1="0" x2="0" y2="9" stroke="var(--soil)" strokeWidth="1" opacity="0.55" />
        </pattern>
        <pattern id="conc" width="6" height="6" patternUnits="userSpaceOnUse">
          <rect width="6" height="6" fill="#E7ECEF" />
          <circle cx="1.5" cy="1.5" r="0.5" fill="#B3BEC6" />
          <circle cx="4.5" cy="4.5" r="0.5" fill="#B3BEC6" />
        </pattern>
        <marker id="arw" markerWidth="8" markerHeight="8" refX="6" refY="3" orient="auto">
          <path d="M0,0 L6,3 L0,6 Z" fill="var(--steel)" />
        </marker>
        <marker id="arwSoil" markerWidth="8" markerHeight="8" refX="6" refY="3" orient="auto">
          <path d="M0,0 L6,3 L0,6 Z" fill="var(--soil)" />
        </marker>
      </defs>

      {/* solo retido */}
      <polygon
        points={`${stemBRb},${yBaseTop} ${stemTRb},${yTop} ${xBack},${yTop} ${xBack},${yBaseTop}`}
        fill="url(#soil)" stroke="var(--soil)" strokeWidth="1" opacity="0.95"
      />
      {/* sobrecarga q — setas no topo do solo */}
      {[0.2, 0.4, 0.6, 0.8].map((t, i) => {
        const x = stemTRb + (xBack - stemTRb) * t;
        return <line key={i} x1={x} y1={yTop - 26} x2={x} y2={yTop - 4} stroke="var(--soil)" strokeWidth="1.4" markerEnd="url(#arwSoil)" />;
      })}
      <line x1={stemTRb} y1={yTop - 28} x2={xBack} y2={yTop - 28} stroke="var(--soil)" strokeWidth="1" />
      <text x={(stemTRb + xBack) / 2} y={yTop - 33} textAnchor="middle" fontSize="11" fill="var(--soil)" fontFamily="var(--mono)">q = {f(o.D15, 0)}</text>

      {/* base */}
      <rect x={X(0)} y={yTop < yBaseTop ? yBaseTop : yBaseTop} width={b * s} height={eb * s}
        fill="url(#conc)" stroke="var(--steel-deep)" strokeWidth="1.6" />
      {/* parede (stem) */}
      <polygon
        points={`${stemBL},${yBaseTop} ${stemBRb},${yBaseTop} ${stemTRb},${yTop} ${stemBL},${yTop}`}
        fill="url(#conc)" stroke="var(--steel-deep)" strokeWidth="1.6"
      />

      {/* diagrama de pressão (trapézio) à direita */}
      <polygon
        points={`${xBack},${yTop} ${xBack + wPx(DE)},${yTop} ${xBack + wPx(pMax)},${yBot} ${xBack},${yBot}`}
        fill="var(--steel)" opacity="0.14" stroke="var(--steel)" strokeWidth="1"
      />
      {[0.15, 0.45, 0.75, 1].map((t, i) => {
        const yy = yTop + (yBot - yTop) * t;
        const p = DE + Eo * t;
        return <line key={i} x1={xBack + wPx(p)} y1={yy} x2={xBack + 2} y2={yy} stroke="var(--steel)" strokeWidth="1.2" markerEnd="url(#arw)" />;
      })}
      <text x={xBack + wPx(pMax) + 6} y={yBot - 2} fontSize="10.5" fill="var(--steel-deep)" fontFamily="var(--mono)">Eo {f(Eo, 0)}</text>
      <text x={xBack + wPx(DE) + 6} y={yTop + 11} fontSize="10.5" fill="var(--steel-deep)" fontFamily="var(--mono)">ΔE {f(DE, 0)}</text>

      {/* resultante Fh */}
      <line x1={xBack + 54} y1={yBar} x2={xBack + 4} y2={yBar} stroke="var(--danger)" strokeWidth="2.4" markerEnd="url(#arw)" style={{ filter: "none" }} />
      <text x={xBack + 58} y={yBar + 4} fontSize="11" fill="var(--danger)" fontFamily="var(--mono)" fontWeight="600">Fh {f(o.N5, 0)}</text>

      {/* cotas ---------------------------------------------------- */}
      {/* H total (esquerda) */}
      {tick(X(0) - 34, yTop, X(0) - 22, yTop)}
      {tick(X(0) - 34, yBot, X(0) - 22, yBot)}
      <line x1={X(0) - 28} y1={yTop} x2={X(0) - 28} y2={yBot} stroke={dim} strokeWidth="1" markerStart="url(#arw)" markerEnd="url(#arw)" opacity="0.6" />
      <text x={X(0) - 40} y={(yTop + yBot) / 2} textAnchor="middle" fontSize="11" fill={dim} fontFamily="var(--mono)"
        transform={`rotate(-90 ${X(0) - 40} ${(yTop + yBot) / 2})`}>H = {f(o.D6, 2)} m</text>

      {/* eBase (esquerda, junto à base) */}
      <text x={X(0) - 8} y={(yBaseTop + yBot) / 2 + 3} textAnchor="end" fontSize="9.5" fill={dim} fontFamily="var(--mono)">e={f(eb, 2)}</text>

      {/* base total (embaixo) */}
      {tick(X(0), yBot + 10, X(0), yBot + 30)}
      {tick(X(b), yBot + 10, X(b), yBot + 30)}
      {tick(X(b1), yBot + 10, X(b1), yBot + 24)}
      <line x1={X(0)} y1={yBot + 26} x2={X(b)} y2={yBot + 26} stroke={dim} strokeWidth="1" markerStart="url(#arw)" markerEnd="url(#arw)" opacity="0.6" />
      <text x={X(b) / 2 + X(0) / 2} y={yBot + 44} textAnchor="middle" fontSize="11" fill={dim} fontFamily="var(--mono)">b = {f(o.D7, 2)} m</text>
      <line x1={X(0)} y1={yBot + 14} x2={X(b1)} y2={yBot + 14} stroke="var(--steel)" strokeWidth="1" opacity="0.7" />
      <text x={(X(0) + X(b1)) / 2} y={yBot + 12} textAnchor="middle" fontSize="9.5" fill="var(--steel-deep)" fontFamily="var(--mono)">b1 {f(b1, 2)}</text>
      <line x1={X(b1)} y1={yBot + 14} x2={X(b)} y2={yBot + 14} stroke="var(--soil)" strokeWidth="1" opacity="0.8" />
      <text x={(X(b1) + X(b)) / 2} y={yBot + 12} textAnchor="middle" fontSize="9.5" fill="var(--soil)" fontFamily="var(--mono)">b2 {f(o.D8, 2)}</text>

      {/* rótulos peças */}
      <text x={(stemBL + stemTRb) / 2} y={(yTop + yBaseTop) / 2} textAnchor="middle" fontSize="10.5" fill="var(--steel-deep)" fontFamily="var(--mono)" transform={`rotate(-90 ${(stemBL + stemTRb) / 2} ${(yTop + yBaseTop) / 2})`}>PAREDE</text>
      <text x={X(b1) / 2 + X(0) / 2} y={(yBaseTop + yBot) / 2 + 4} textAnchor="middle" fontSize="9.5" fill="var(--ink-soft)" fontFamily="var(--mono)">PÉ</text>
      <text x={(X(b1) + X(b)) / 2} y={(yBaseTop + yBot) / 2 + 4} textAnchor="middle" fontSize="9.5" fill="var(--ink-soft)" fontFamily="var(--mono)">TALÃO</text>
    </svg>
  );
}

/* ---------- pequenas peças de UI ---------- */
function Field({ label, cell, unit, value, onChange, hint }) {
  return (
    <label className="fld">
      <span className="fld-top">
        <span className="fld-label">{label}</span>
        <span className="fld-cell">{cell}</span>
      </span>
      <span className="fld-in">
        <input value={value} onChange={(e) => onChange(e.target.value)} inputMode="decimal" spellCheck={false} />
        <span className="fld-unit">{unit}</span>
      </span>
      {hint && <span className="fld-hint">{hint}</span>}
    </label>
  );
}

function Row({ label, cell, value, unit, strong }) {
  return (
    <div className={"row" + (strong ? " row-strong" : "")}>
      <span className="row-l">{label}{cell && <em className="row-cell">{cell}</em>}</span>
      <span className="row-v">{value}<i className="row-u">{unit}</i></span>
    </div>
  );
}

function Verdict({ ok, okText = "OK", noText = "REDIMENSIONE", warn }) {
  const cls = warn ? "vd vd-warn" : ok ? "vd vd-ok" : "vd vd-no";
  return <span className={cls}>{warn ? "ATENÇÃO" : ok ? okText : noText}</span>;
}

/* ================================================================== */
function toEmbed(u) {
  if (!u) return null;
  let m = u.match(/(?:youtube\.com\/watch\?v=|youtu\.be\/|youtube\.com\/embed\/)([\w-]{6,})/);
  if (m) return { type: "iframe", src: "https://www.youtube.com/embed/" + m[1] };
  m = u.match(/vimeo\.com\/(?:video\/)?(\d+)/);
  if (m) return { type: "iframe", src: "https://player.vimeo.com/video/" + m[1] };
  if (/\.mp4($|\?)/i.test(u)) return { type: "video", src: u };
  return { type: "iframe", src: u };
}

function VideoHero() {
  const emb = toEmbed(VIDEO_URL);
  return (
    <section className="vhero" id="video">
      <div className="vhero-head">
        <span className="vhero-eyebrow">Comece por aqui</span>
        <h2 className="vhero-title">Como usar a calculadora</h2>
        <p className="vhero-sub">Assista ao passo a passo de como preencher os dados e ler as verificações de tombamento, deslizamento e tensão no solo.</p>
      </div>
      <div className="vhero-frame">
        {emb ? (
          emb.type === "video"
            ? <video src={emb.src} controls playsInline />
            : <iframe src={emb.src} title="Como usar a calculadora" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" allowFullScreen />
        ) : (
          <div className="vhero-empty">
            <div className="vhero-play">&#9654;</div>
            <p>Vídeo ainda não configurado</p>
            <span>Cole o link em <code>VIDEO_URL</code> no topo do código.</span>
          </div>
        )}
      </div>
    </section>
  );
}

export default function App() {
  const [I, setI] = useState(DEFAULTS);
  const [tab, setTab] = useState("result");
  const [showSheet, setShowSheet] = useState(false);
  const [showAudit, setShowAudit] = useState(false);
  const set = (k) => (v) => setI((p) => ({ ...p, [k]: v }));
  const reset = () => setI(DEFAULTS);
  const o = useMemo(() => compute(I), [I]);

  // avisos do engenheiro (interpretação — NÃO constam como veredicto na planilha)
  const desliza = o.N14 >= 1.5;
  const soloDireto = o.N9 <= o.N7 && o.N10 >= 0; // Tmax≤Tadm e sem tração
  const temTracao = o.N10 < 0;

  return (
    <div className="app">
      <style>{CSS}</style>

      <header className="hd">
        <div className="hd-brand">
          <img className="hd-logo" src={LOGO_INEC} alt="INEC — Instituto Nacional de Engenharia Civil" />
          <div className="hd-div" />
          <div className="hd-txt">
            <h1>Muro de Arrimo <span>· verificação estrutural</span></h1>
            <p>Calculadora técnica INEC — empuxos, tombamento, deslizamento e tensões no solo.</p>
          </div>
        </div>
        <div className="hd-actions">
          <a className="hd-video" href="#video">▶ Como usar</a>
          <button className="hd-reset" onClick={reset}>↺ Valores da planilha</button>
        </div>
      </header>

      <VideoHero />

      <div className="notice">
        <strong>Ferramenta de apoio — a verificação final é do engenheiro responsável.</strong>{" "}
        Reproduz as fórmulas da planilha e não substitui o projeto estrutural nem as verificações normativas
        (NBR 6118 / 6122 / 11682). Confira todos os dados, hipóteses e resultados antes de qualquer uso em obra.
        <button className="notice-more" onClick={() => setShowAudit((s) => !s)}>ver auditoria de fórmulas</button>
      </div>

      <a className="cta-pontes" href={PONTES_URL} target="_blank" rel="noopener noreferrer">
        <div className="cta-pontes-txt">
          <span className="cta-eyebrow">Pós-graduação em Pontes e Viadutos · INEC</span>
          <strong>Quer aprender a projetar pontes na prática?</strong>
          <span className="cta-sub">Conheça a pós-graduação em que você finaliza projetando pelo menos 2 pontes no seu portfólio.</span>
        </div>
        <span className="cta-btn">Conhecer a pós de Pontes →</span>
      </a>

      <main className="grid">
        {/* ---------------- ENTRADAS ---------------- */}
        <section className="col-in">
          <div className="card">
            <div className="card-h"><span className="idx">1</span>Geometria <em>(m)</em></div>
            <div className="fields">
              <Field label="Altura útil (h)" cell="D5" unit="m" value={I.h} onChange={set("h")} />
              <Field label="Base interna · talão (b2)" cell="D8" unit="m" value={I.b2} onChange={set("b2")} />
              <Field label="Base externa · pé (b1)" cell="D9" unit="m" value={I.b1} onChange={set("b1")} />
              <Field label="Espessura da base" cell="D10" unit="m" value={I.eBase} onChange={set("eBase")} />
              <Field label="Parede no pé (e1)" cell="D11" unit="m" value={I.e1Pe} onChange={set("e1Pe")} />
              <Field label="Parede no topo (e2)" cell="D12" unit="m" value={I.e2Topo} onChange={set("e2Topo")} />
            </div>
            <div className="card-derived">
              <span>H total <b>{f(o.D6, 2)}</b> m</span>
              <span>base b <b>{f(o.D7, 2)}</b> m</span>
              <span>e média <b>{f(o.D13, 2)}</b> m</span>
            </div>
          </div>

          <div className="card">
            <div className="card-h"><span className="idx">2</span>Cargas &amp; solo</div>
            <div className="fields">
              <Field label="Peso específico solo (γ)" cell="D14" unit="kgf/m³" value={I.gSolo} onChange={set("gSolo")} />
              <Field label="Sobrecarga (q)" cell="D15" unit="kgf/m²" value={I.q} onChange={set("q")} />
              <Field label="Majorador de sobrecarga" cell="D16" unit="–" value={I.maj} onChange={set("maj")} />
              <Field label="γ·Ka (pressão na parede)" cell="D17" unit="kgf/m³" value={I.gKa} onChange={set("gKa")} />
              <Field label="Ângulo de atrito (φ)" cell="N8" unit="°" value={I.phi} onChange={set("phi")} />
              <Field label="Tensão admissível (Tadm)" cell="N7" unit="kgf/cm²" value={I.Tadm} onChange={set("Tadm")} hint="usada só para conferência" />
            </div>
          </div>

          <div className="const">
            <div className="const-h">Constantes fixas (conforme planilha)</div>
            <div className="const-b">
              <span>γ concreto <b>{GAMMA_C}</b> kgf/m³</span>
              <span>γf <b>{GF}</b></span>
              <span>fator talão <b>{FSOB}</b></span>
              <span>cobrim. cis. <b>{COBR}</b> cm</span>
            </div>
          </div>
        </section>

        {/* ---------------- DESENHO ---------------- */}
        <section className="col-draw">
          <div className="card card-draw">
            <div className="card-h">Seção transversal <em>· escala automática</em></div>
            <WallSection o={o} />
            <div className="legend">
              <span><i className="lg lg-conc" />concreto</span>
              <span><i className="lg lg-soil" />solo retido</span>
              <span><i className="lg lg-press" />empuxo</span>
              <span><i className="lg lg-fh" />resultante Fh</span>
            </div>
          </div>

          {/* checagens principais */}
          <div className="checks">
            <div className={"chk " + (o.CS_ok ? "chk-ok" : "chk-no")}>
              <div className="chk-t">Tombamento <em>J18/L18</em></div>
              <div className="chk-v">{f(o.J18, 3)}</div>
              <div className="chk-b"><span>CS &gt; 1,5</span><Verdict ok={o.CS_ok} /></div>
            </div>
            <div className={"chk " + (o.CIS_ok ? "chk-ok" : "chk-no")}>
              <div className="chk-t">Cisalhamento no pé <em>N6/P6</em></div>
              <div className="chk-v">{f(o.N6, 3)}<i>kgf/cm²</i></div>
              <div className="chk-b"><span>td &lt; 6</span><Verdict ok={o.CIS_ok} /></div>
            </div>
            <div className={"chk " + (desliza ? "chk-ok" : "chk-warn")}>
              <div className="chk-t">Deslizamento <em>N14 · complementar</em></div>
              <div className="chk-v">{f(o.N14, 3)}</div>
              <div className="chk-b"><span>Fhr/Fh ≥ 1,5</span><Verdict ok={desliza} warn={!desliza} /></div>
            </div>
          </div>
        </section>

        {/* ---------------- RESULTADOS ---------------- */}
        <section className="col-out">
          <div className="tabs">
            {[["result", "Esforços & momentos"], ["solo", "Tensões no solo"]].map(([k, t]) => (
              <button key={k} className={tab === k ? "tab tab-on" : "tab"} onClick={() => setTab(k)}>{t}</button>
            ))}
          </div>

          {tab === "result" && (
            <div className="card">
              <div className="card-h"><span className="idx">2</span>Empuxos e cargas atuantes</div>
              <Row label="Empuxo do solo" cell="J5" value={f(o.J5, 1)} unit="kgf/m²" />
              <Row label="Empuxo de sobrecarga" cell="J6" value={f(o.J6, 1)} unit="kgf/m²" />
              <Row label="P1 · peso da parede" cell="J7" value={f(o.J7, 1)} unit="kgf/m" />
              <Row label="P2 · peso da base" cell="J8" value={f(o.J8, 1)} unit="kgf/m" />
              <Row label="P3 · peso da terra na base" cell="J9" value={f(o.J9, 1)} unit="kgf/m" />
              <Row label="P4 · sobrecarga" cell="J10" value={f(o.J10, 1)} unit="kgf/m" />
              <Row label="Carga total vertical" cell="J11" value={f(o.J11, 1)} unit="kgf/m" strong />

              <div className="card-h card-h2"><span className="idx">3</span>Momentos</div>
              <Row label="Momento de tombamento (Mt)" cell="J15" value={f(o.J15, 1)} unit="kgf·m/m" />
              <Row label="Momento resistente (Mr)" cell="J17" value={f(o.J17, 1)} unit="kgf·m/m" />
              <div className="row row-strong">
                <span className="row-l">Coef. de segurança <em className="row-cell">J18</em></span>
                <span className="row-v">{f(o.J18, 3)} <Verdict ok={o.CS_ok} /></span>
              </div>
              <Row label="Mk · momento fletor no pé da parede" cell="J16" value={f(o.J16, 1)} unit="kgf·m/m" />
              <div className="sub">Parcelas do momento resistente</div>
              <Row label="M1 (base externa)" cell="J21" value={f(o.J21, 1)} unit="kgf·m/m" />
              <Row label="M2" cell="J22" value={f(o.J22, 1)} unit="kgf·m/m" />
              <Row label="M3" cell="J23" value={f(o.J23, 1)} unit="kgf·m/m" />
              <Row label="M4" cell="J24" value={f(o.J24, 1)} unit="kgf·m/m" />
              <div className="sub">Momentos para tensão no solo (Mo)</div>
              <Row label="Mo1 (base interna)" cell="J27" value={f(o.J27, 1)} unit="kgf·m/m" />
              <Row label="Mo3" cell="J29" value={f(o.J29, 1)} unit="kgf·m/m" />
              <Row label="Mo4" cell="J30" value={f(o.J30, 1)} unit="kgf·m/m" />
              <Row label="Mo total" cell="J31" value={f(o.J31, 1)} unit="kgf·m/m" strong />

              <div className="card-h card-h2"><span className="idx">5</span>Volumes e pesos</div>
              <Row label="Volume do muro (Vm)" cell="N19" value={f(o.N19, 3)} unit="m³/m" />
              <Row label="Peso do muro (Pm)" cell="N20" value={f(o.N20, 1)} unit="kgf/m" />
              <Row label="Volume terra sobre base (Vt)" cell="N21" value={f(o.N21, 3)} unit="m³/m" />
              <Row label="Peso da terra (Pt)" cell="N22" value={f(o.N22, 1)} unit="kgf/m" />
            </div>
          )}

          {tab === "solo" && (
            <div className="card">
              <div className="card-h"><span className="idx">4</span>Reações e tensão no solo</div>
              <Row label="Reação horizontal (Fh)" cell="N5" value={f(o.N5, 1)} unit="kgf/m" />
              <div className="row">
                <span className="row-l">Cisalhamento (td) <em className="row-cell">N6</em></span>
                <span className="row-v">{f(o.N6, 3)} <i className="row-u">kgf/cm²</i> <Verdict ok={o.CIS_ok} /></span>
              </div>
              <Row label="Tensão máxima (Tmax)" cell="N9" value={f(o.N9, 3)} unit="kgf/cm²" strong />
              <Row label="Tensão mínima (Tmin)" cell="N10" value={f(o.N10, 3)} unit="kgf/cm²" strong />
              <Row label="Tensão média T1" cell="N11" value={f(o.N11, 3)} unit="kgf/cm²" />
              <Row label="Tensão média T2" cell="N12" value={f(o.N12, 3)} unit="kgf/cm²" />
              <Row label="Tensão admissível (Tadm)" cell="N7" value={f(o.N7, 3)} unit="kgf/cm²" />
              <Row label="Força horiz. resistente (Fhr)" cell="N13" value={f(o.N13, 1)} unit="kgf/m" />
              <Row label="CS horizontal (Fhr/Fh)" cell="N14" value={f(o.N14, 3)} unit="" />
              <Row label="Área comprimida / área da base" cell="N15" value={f(o.N15, 3)} unit="" />

              <div className={"advice " + (temTracao ? "advice-red" : soloDireto ? "advice-ok" : "advice-amber")}>
                {temTracao ? (
                  <>Tmin negativa ({f(o.N10, 3)} kgf/cm²) → há <b>tração / levantamento do talão</b>: parte da base tende a descolar do solo. A sapata direta, como está, não está adequada — reavalie a geometria (base / talão) ou adote fundação profunda.</>
                ) : soloDireto ? (
                  <>Tmax ({f(o.N9, 3)}) ≤ Tadm ({f(o.N7, 3)}) e sem tração — sapata direta plausível. <b>Confirme</b> com a sondagem e a NBR 6122.</>
                ) : (
                  <>Tmax ({f(o.N9, 3)} kgf/cm²) &gt; Tadm ({f(o.N7, 3)} kgf/cm²): a tensão de pico excede a admissível informada. Reavalie geometria, o Tadm real da sondagem ou adote fundação profunda.</>
                )}
              </div>
              <p className="mini">Observação: a planilha não emite veredicto automático para deslizamento nem para Tmax×Tadm — os avisos acima são interpretação de apoio e devem ser confirmados.</p>
            </div>
          )}

        </section>
      </main>

      {/* ---------------- AUDITORIA DE FÓRMULAS ---------------- */}
      {showAudit && (
        <section className="audit">
          <div className="audit-h">
            Auditoria — cada saída e sua fórmula exata na planilha
            <button onClick={() => setShowAudit(false)}>fechar</button>
          </div>
          <div className="audit-grid">
            {AUDIT.map((a) => (
              <div key={a[0]} className="au">
                <span className="au-c">{a[0]}</span>
                <span className="au-n">{a[1]}</span>
                <code className="au-f">{a[2]}</code>
              </div>
            ))}
          </div>
        </section>
      )}

      {/* ---------------- PLANILHA ORIGINAL ---------------- */}
      <section className="sheet">
        <button className="sheet-toggle" onClick={() => setShowSheet((s) => !s)}>
          {showSheet ? "▾" : "▸"} Planilha original (imagem de referência)
        </button>
        {showSheet && (
          <div className="sheet-body">
            <img src={SHEET_IMG} alt="Planilha original de cálculo do muro de arrimo" />
            <p className="mini">Imagem da planilha "Caludo_de_muros_de_Arrimo.xlsx" tal como fornecida, para conferência lado a lado.</p>
          </div>
        )}
      </section>

      {/* ---------------- CTA PROTENSÃO ---------------- */}
      <a className="cta-pontes cta-prot" href={PROTENDIDO_URL} target="_blank" rel="noopener noreferrer">
        <div className="cta-pontes-txt">
          <span className="cta-eyebrow">Pós-graduação em Concreto Protendido · INEC</span>
          <strong>Projete estruturas de concreto</strong>
          <span className="cta-sub">Da concepção ao detalhamento, armado e protendido.</span>
        </div>
        <span className="cta-btn">Conhecer a pós de Protensão →</span>
      </a>

      {/* ---------------- TERMO ---------------- */}
      <footer className="foot">
        <div className="foot-brand">
          <img className="foot-logo" src={LOGO_INEC} alt="INEC" />
          <span>Instituto Nacional de Engenharia Civil</span>
        </div>
        <div className="foot-h">Aviso técnico e limitação de responsabilidade</div>
        <p>
          Esta ferramenta apenas reproduz as fórmulas da planilha fornecida e destina-se a <b>apoio de cálculo e conferência</b>.
          Os resultados <b>não substituem</b> o projeto estrutural, o dimensionamento do concreto armado e da fundação, nem as
          verificações exigidas pelas normas aplicáveis (ABNT NBR 6118, NBR 6122, NBR 11682, entre outras). O engenheiro
          responsável deve conferir todos os dados de entrada, hipóteses de cálculo, fórmulas e resultados antes de qualquer
          aplicação em projeto ou obra. A responsabilidade técnica pelas decisões e pelo uso dos resultados é integralmente do
          profissional habilitado. Os autores desta ferramenta não respondem por erros, omissões ou uso indevido.
        </p>
      </footer>
    </div>
  );
}

/* lista para a auditoria de fórmulas */
const AUDIT = [
  ["D6", "Altura total H", "=D5+D10"],
  ["D7", "Base total", "=D8+D9"],
  ["D13", "Espessura média", "=AVERAGE(D12,D11)"],
  ["D18", "Altura equivalente Dh", "=D15*D16/D14"],
  ["J5", "Empuxo solo Eo", "=D17*D6"],
  ["J6", "Empuxo sobrecarga DE", "=D17*D18"],
  ["J7", "P1 peso da parede", "=D13*D5*2500"],
  ["J8", "P2 peso da base", "=D10*D7*2500"],
  ["J9", "P3 peso terra na base", "=N22"],
  ["J10", "P4 sobrecarga", "=D15*(D8-D13)*1.36"],
  ["J11", "Carga total vertical", "=SUM(J7:J10)"],
  ["J15", "Momento tombamento Mt", "=D6^2*(3*J6+J5)/6"],
  ["J16", "Mk momento em e1", "=D5^2*(3*J6+(D17*D5))/6"],
  ["J17", "Momento resistente Mr", "=SUM(J21:J24)"],
  ["J18", "Coef. segurança", "=J17/J15  · OK se >1,5 (L18)"],
  ["J21", "M1 base externa", "=J7*(D13/2+D9)"],
  ["J22", "M2", "=J8*D7/2"],
  ["J23", "M3", "=J9*(D8+D13)/2"],
  ["J24", "M4", "=J10*((D8+D13)/2+D9)"],
  ["J27", "Mo1 base interna", "=J7*((D7-D13)/2-D9)"],
  ["J29", "Mo3", "=-J9*(D7-D8+D13)/2"],
  ["J30", "Mo4", "=-J10*(D7-D8+D13)/2"],
  ["J31", "Mo total", "=SUM(J27:J30)+J15"],
  ["N5", "Reação horizontal Fh", "=J6*D6+J5*D6/2"],
  ["N6", "Cisalhamento td", "=N5*1.4/100/(100*D11-5) · OK se <6 (P6)"],
  ["N9", "Tensão máxima", "=N12+N11"],
  ["N10", "Tensão mínima", "=N11-N12"],
  ["N11", "Tensão média T1", "=J11/100/(100*D7)"],
  ["N12", "Tensão média T2", "=J31*6/((100*D7)^2)"],
  ["N13", "Força horiz. resistente Fhr", "=TAN(N8*PI()/180)*J11"],
  ["N14", "CS horizontal", "=N13/N5"],
  ["N15", "Área comprimida/base", "=N9/(N9-N10)"],
  ["N19", "Volume do muro", "=(D7+D5)*D13"],
  ["N20", "Peso do muro", "=N19*2500"],
  ["N21", "Volume terra s/ base", "=(D8-D13)*D5"],
  ["N22", "Peso da terra", "=N21*D14"],
];

/* ========================== CSS ========================== */
const CSS = `
@import url('https://fonts.googleapis.com/css2?family=Bebas+Neue&family=Inter:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500;600&display=swap');
:root{
  --paper:#EBEEF0; --panel:#FFFFFF; --panel2:#F4F6F8;
  --ink:#161a1e; --ink-soft:#586170; --line:#D6DDE2;
  --steel:#222c38; --steel-deep:#0f1620; --concrete:#9AA5AD;
  --soil:#B5852F; --soil-soft:#F0E2C0;
  --gold:#F1C400; --gold-deep:#8a6f00; --orange:#E8730C; --black:#111417;
  --ok:#1C7A4D; --ok-bg:#E6F3EC; --warn:#A9620F; --warn-bg:#FBEEDD;
  --danger:#B23B2E; --danger-bg:#FBE9E7;
  --mono:'JetBrains Mono',ui-monospace,monospace;
  --disp:'Bebas Neue',Impact,system-ui,sans-serif;
  --body:'Inter',system-ui,sans-serif;
}
*{box-sizing:border-box}
.app{background:var(--paper);color:var(--ink);font-family:var(--body);
  min-height:100vh;padding:22px;max-width:1360px;margin:0 auto;line-height:1.45;
  -webkit-font-smoothing:antialiased}

/* header */
.hd{display:flex;align-items:center;justify-content:space-between;gap:14px;
  background:var(--black);border-radius:12px;padding:14px 18px;margin-bottom:14px;flex-wrap:wrap}
.hd-brand{display:flex;align-items:center;gap:14px;min-width:0}
.hd-logo{width:52px;height:52px;flex:0 0 auto;border-radius:8px}
.hd-div{width:1px;align-self:stretch;background:rgba(255,255,255,.16);margin:2px 0}
.hd-txt{min-width:0}
.hd-txt h1{font-family:var(--disp);font-weight:400;font-size:27px;letter-spacing:.04em;margin:0;color:#fff;line-height:1}
.hd-txt h1 span{color:var(--gold);font-size:16px;letter-spacing:.06em}
.hd-txt p{margin:4px 0 0;color:#AEB6C0;font-size:12.5px}
.hd-actions{display:flex;gap:8px;align-items:center;flex-wrap:wrap}
.hd-video{font-family:var(--mono);font-size:12px;color:#111;background:var(--gold);
  border:1px solid var(--gold);border-radius:7px;padding:8px 12px;text-decoration:none;font-weight:600}
.hd-video:hover{filter:brightness(1.06)}
.hd-reset{font-family:var(--mono);font-size:12px;color:#DFE4EA;
  background:transparent;border:1px solid rgba(255,255,255,.28);border-radius:7px;padding:8px 12px;cursor:pointer}
.hd-reset:hover{border-color:var(--gold);color:#fff}

/* notice */
.notice{background:var(--panel);border:1px solid var(--line);border-left:3px solid var(--gold);
  border-radius:8px;padding:11px 14px;font-size:12.5px;color:var(--ink-soft);margin-bottom:16px}
.notice strong{color:var(--ink)}
.notice-more{margin-left:6px;font-family:var(--mono);font-size:11.5px;color:var(--gold-deep);
  background:none;border:none;text-decoration:underline;cursor:pointer;padding:0}

/* grid */
.grid{display:grid;grid-template-columns:290px minmax(0,1fr) minmax(0,1fr);gap:16px;align-items:start}
@media(max-width:1080px){.grid{grid-template-columns:1fr 1fr}.col-in{grid-column:1/-1;
  display:grid;grid-template-columns:1fr 1fr;gap:14px;align-content:start}}
@media(max-width:720px){.grid{grid-template-columns:1fr}.col-in{grid-template-columns:1fr}}

/* card */
.card{background:var(--panel);border:1px solid var(--line);border-radius:10px;
  padding:14px 15px 15px;margin-bottom:14px}
.card-h{font-family:var(--disp);font-weight:600;font-size:13.5px;letter-spacing:.01em;
  color:var(--ink);display:flex;align-items:center;gap:8px;margin-bottom:11px}
.card-h em{color:var(--ink-soft);font-weight:500;font-style:normal;font-size:12px}
.card-h2{margin-top:18px;padding-top:14px;border-top:1px solid var(--line)}
.idx{width:20px;height:20px;border-radius:5px;background:var(--steel);color:#fff;
  font-family:var(--mono);font-size:12px;display:grid;place-items:center;flex:0 0 auto}

/* fields */
.fields{display:flex;flex-direction:column;gap:9px}
.fld{display:flex;flex-direction:column;gap:3px}
.fld-top{display:flex;justify-content:space-between;align-items:baseline;gap:6px}
.fld-label{font-size:12px;color:var(--ink)}
.fld-cell{font-family:var(--mono);font-size:10px;color:var(--ink-soft);
  background:var(--panel2);border:1px solid var(--line);border-radius:4px;padding:0 4px}
.fld-in{display:flex;align-items:center;border:1px solid var(--line);border-radius:6px;
  background:var(--panel2);overflow:hidden}
.fld-in:focus-within{border-color:var(--gold);box-shadow:0 0 0 2px rgba(241,196,0,.22)}
.fld-in input{flex:1;min-width:0;border:none;background:none;outline:none;
  font-family:var(--mono);font-size:14px;color:var(--steel-deep);padding:7px 9px;font-weight:500}
.fld-unit{font-family:var(--mono);font-size:10.5px;color:var(--ink-soft);
  padding:0 9px;border-left:1px solid var(--line);white-space:nowrap}
.fld-hint{font-size:10.5px;color:var(--ink-soft);font-style:italic}
.card-derived{display:flex;flex-wrap:wrap;gap:6px 14px;margin-top:12px;padding-top:11px;
  border-top:1px dashed var(--line);font-size:11.5px;color:var(--ink-soft);font-family:var(--mono)}
.card-derived b{color:var(--steel-deep);font-weight:600}

/* constantes */
.const{border:1px dashed var(--line);border-radius:9px;padding:10px 12px;background:var(--panel2)}
.const-h{font-size:11px;color:var(--ink-soft);text-transform:uppercase;letter-spacing:.06em;margin-bottom:6px}
.const-b{display:flex;flex-wrap:wrap;gap:5px 14px;font-family:var(--mono);font-size:11.5px;color:var(--ink-soft)}
.const-b b{color:var(--ink);font-weight:600}

/* desenho */
.card-draw{padding-bottom:9px}
.legend{display:flex;flex-wrap:wrap;gap:5px 16px;justify-content:center;margin-top:4px;
  font-size:11px;color:var(--ink-soft);font-family:var(--mono)}
.legend span{display:inline-flex;align-items:center;gap:5px}
.lg{width:12px;height:10px;border-radius:2px;display:inline-block}
.lg-conc{background:#E7ECEF;border:1px solid var(--steel-deep)}
.lg-soil{background:var(--soil-soft);border:1px solid var(--soil)}
.lg-press{background:rgba(31,92,130,.16);border:1px solid var(--steel)}
.lg-fh{background:var(--danger)}

/* checks */
.checks{display:grid;grid-template-columns:1fr 1fr 1fr;gap:10px}
@media(max-width:520px){.checks{grid-template-columns:1fr}}
.chk{background:var(--panel);border:1px solid var(--line);border-radius:10px;padding:11px 12px;
  border-top:3px solid var(--concrete)}
.chk-ok{border-top-color:var(--ok)} .chk-no{border-top-color:var(--danger)} .chk-warn{border-top-color:var(--warn)}
.chk-t{font-size:11px;color:var(--ink-soft);line-height:1.3}
.chk-t em{display:block;font-style:normal;font-family:var(--mono);font-size:9.5px;opacity:.75;margin-top:1px}
.chk-v{font-family:var(--mono);font-weight:600;font-size:24px;color:var(--ink);margin:5px 0 6px}
.chk-v i{font-style:normal;font-size:11px;color:var(--ink-soft);margin-left:4px;font-weight:400}
.chk-b{display:flex;justify-content:space-between;align-items:center;font-family:var(--mono);
  font-size:10.5px;color:var(--ink-soft)}

/* veredicto */
.vd{font-family:var(--mono);font-size:10.5px;font-weight:600;padding:2px 7px;border-radius:20px;letter-spacing:.02em}
.vd-ok{background:var(--ok-bg);color:var(--ok)}
.vd-no{background:var(--danger-bg);color:var(--danger)}
.vd-warn{background:var(--warn-bg);color:var(--warn)}

/* tabs */
.tabs{display:flex;gap:6px;margin-bottom:12px;flex-wrap:wrap}
.tab{font-family:var(--disp);font-weight:500;font-size:12.5px;color:var(--ink-soft);
  background:var(--panel);border:1px solid var(--line);border-radius:7px;padding:7px 13px;cursor:pointer}
.tab-on{background:var(--gold);color:#111417;border-color:var(--gold);font-weight:600}

/* rows */
.row{display:flex;justify-content:space-between;align-items:baseline;gap:10px;
  padding:6px 0;border-bottom:1px solid var(--line);font-size:12.5px}
.row:last-child{border-bottom:none}
.row-l{color:var(--ink-soft)}
.row-cell{font-family:var(--mono);font-size:10px;color:var(--steel);font-style:normal;
  margin-left:6px;opacity:.8}
.row-v{font-family:var(--mono);font-size:13.5px;color:var(--ink);font-weight:500;white-space:nowrap}
.row-u{font-style:normal;font-size:10.5px;color:var(--ink-soft);margin-left:4px;font-weight:400}
.row-strong{background:var(--panel2);margin:3px -8px;padding:8px;border-radius:6px;border-bottom:none}
.row-strong .row-l{color:var(--ink);font-weight:600}
.row-strong .row-v{font-weight:600;font-size:15px;color:var(--steel-deep)}
.sub{font-family:var(--mono);font-size:10.5px;color:var(--ink-soft);text-transform:uppercase;
  letter-spacing:.05em;margin:13px 0 3px;padding-top:9px;border-top:1px dashed var(--line)}

/* advice */
.advice{margin-top:13px;padding:11px 13px;border-radius:8px;font-size:12.5px;line-height:1.5}
.advice-red{background:var(--danger-bg);color:#7a2318;border:1px solid #eabfb9}
.advice-amber{background:var(--warn-bg);color:#7a480d;border:1px solid #ecd4ad}
.advice-ok{background:var(--ok-bg);color:#14512f;border:1px solid #b9dcc7}
.mini{font-size:11px;color:var(--ink-soft);margin:10px 0 0;line-height:1.45}

/* audit */
.audit{background:var(--panel);border:1px solid var(--line);border-radius:10px;padding:14px 15px;margin:2px 0 16px}
.audit-h{font-family:var(--disp);font-weight:600;font-size:13px;display:flex;
  justify-content:space-between;align-items:center;margin-bottom:11px}
.audit-h button{font-family:var(--mono);font-size:11px;color:var(--steel);background:none;
  border:1px solid var(--line);border-radius:6px;padding:4px 9px;cursor:pointer}
.audit-grid{display:grid;grid-template-columns:1fr 1fr;gap:6px 18px}
@media(max-width:720px){.audit-grid{grid-template-columns:1fr}}
.au{display:grid;grid-template-columns:44px 1fr;gap:4px 8px;align-items:baseline;
  padding:5px 0;border-bottom:1px solid var(--line)}
.au-c{font-family:var(--mono);font-size:11px;font-weight:600;color:#fff;background:var(--steel);
  border-radius:4px;text-align:center;padding:1px 0}
.au-n{font-size:12px;color:var(--ink)}
.au-f{grid-column:2;font-family:var(--mono);font-size:11px;color:var(--steel-deep);
  background:var(--panel2);border:1px solid var(--line);border-radius:5px;padding:3px 7px;word-break:break-all}

/* sheet */
.sheet{margin-bottom:16px}
.sheet-toggle{width:100%;text-align:left;font-family:var(--disp);font-weight:600;font-size:13px;
  color:var(--ink);background:var(--panel);border:1px solid var(--line);border-radius:9px;
  padding:11px 14px;cursor:pointer}
.sheet-toggle:hover{border-color:var(--steel)}
.sheet-body{background:var(--panel);border:1px solid var(--line);border-top:none;
  border-radius:0 0 10px 10px;padding:14px;margin-top:-4px}
.sheet-body img{width:100%;height:auto;border:1px solid var(--line);border-radius:6px;display:block}

/* footer */
.foot{background:#F1EEE7;border:1px solid #E0D8C8;border-radius:10px;padding:15px 17px}
.foot-h{font-family:var(--disp);font-weight:600;font-size:13px;color:#6b5a2f;margin-bottom:6px}
.foot p{margin:0;font-size:12px;color:#6b6252;line-height:1.55}
.foot b{color:#4a4436}

/* --- INEC branding --- */
.card-h,.tab,.foot-h,.audit-h,.sheet-toggle{letter-spacing:.03em}
.foot-brand{display:flex;align-items:center;gap:10px;margin-bottom:10px}
.foot-logo{width:34px;height:34px;border-radius:6px}
.foot-brand span{font-family:var(--mono);font-size:11.5px;color:#6b5a2f;letter-spacing:.03em}

/* CTA Pontes (hero) */
.cta-pontes{display:flex;align-items:center;justify-content:space-between;gap:16px;text-decoration:none;
  background:linear-gradient(100deg,#141821,#1d2430);border:1px solid #2a3340;border-left:4px solid var(--gold);
  border-radius:12px;padding:16px 18px;margin-bottom:16px;flex-wrap:wrap}
.cta-pontes:hover{border-color:var(--gold)}
.cta-pontes-txt{display:flex;flex-direction:column;gap:3px;min-width:0}
.cta-eyebrow{font-family:var(--mono);font-size:11px;letter-spacing:.05em;color:var(--gold);text-transform:uppercase}
.cta-pontes-txt strong{font-family:var(--disp);font-weight:400;font-size:24px;letter-spacing:.03em;color:#fff;line-height:1.05}
.cta-sub{font-size:12.5px;color:#B9C0CA;max-width:64ch}
.cta-btn{flex:0 0 auto;font-family:var(--body);font-weight:600;font-size:13.5px;color:#111417;
  background:var(--gold);border-radius:8px;padding:11px 16px;white-space:nowrap}
.cta-pontes:hover .cta-btn{filter:brightness(1.06)}

/* CTA band (dois programas) */
.cta-band{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-bottom:16px}
@media(max-width:640px){.cta-band{grid-template-columns:1fr}}
.prog{display:flex;flex-direction:column;gap:4px;text-decoration:none;background:var(--panel);
  border:1px solid var(--line);border-radius:11px;padding:15px 16px 15px 19px;position:relative;transition:transform .08s}
.prog::before{content:"";position:absolute;left:0;top:0;bottom:0;width:4px;border-radius:11px 0 0 11px}
.prog-pontes::before{background:var(--gold)}
.prog-prot::before{background:var(--orange)}
.prog:hover{border-color:#c2ccd4;transform:translateY(-1px)}
.prog-tag{font-family:var(--mono);font-size:10.5px;letter-spacing:.04em;text-transform:uppercase}
.prog-pontes .prog-tag{color:var(--gold-deep)}
.prog-prot .prog-tag{color:var(--orange)}
.prog strong{font-family:var(--disp);font-weight:400;font-size:21px;letter-spacing:.02em;color:var(--ink)}
.prog-sub{font-size:12px;color:var(--ink-soft)}
.prog-go{margin-top:4px;font-family:var(--body);font-weight:600;font-size:12.5px;color:var(--ink)}
.prog-pontes:hover .prog-go{color:var(--gold-deep)}
.prog-prot:hover .prog-go{color:var(--orange)}

/* Video hero (head) */
.vhero{background:linear-gradient(100deg,#12161d,#1c232e);border:1px solid #2a3340;border-radius:14px;
  padding:18px;margin-bottom:16px;display:grid;grid-template-columns:1fr 1.12fr;gap:20px;align-items:center}
@media(max-width:820px){.vhero{grid-template-columns:1fr}}
.vhero-head{min-width:0}
.vhero-eyebrow{font-family:var(--mono);font-size:11px;letter-spacing:.06em;color:var(--gold);text-transform:uppercase}
.vhero-title{font-family:var(--disp);font-weight:400;font-size:30px;letter-spacing:.03em;color:#fff;margin:6px 0}
.vhero-sub{font-size:13px;color:#B9C0CA;margin:0;max-width:48ch}
.vhero-frame{position:relative;width:100%;aspect-ratio:16/9;border-radius:10px;overflow:hidden;
  background:#0c0f14;border:1px solid #2a3340}
.vhero-frame iframe,.vhero-frame video{position:absolute;inset:0;width:100%;height:100%;border:0}
.vhero-empty{position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;
  gap:2px;text-align:center;color:#8a93a0;padding:16px}
.vhero-play{width:56px;height:56px;border-radius:50%;background:var(--gold);color:#111417;font-size:20px;
  display:grid;place-items:center;padding-left:4px;margin-bottom:8px}
.vhero-empty p{margin:0;color:#cfd5dd;font-weight:600;font-family:var(--body)}
.vhero-empty span{font-size:11.5px;font-family:var(--mono)}
.vhero-empty code{background:#222c38;color:var(--gold);padding:1px 5px;border-radius:4px}

/* CTA Protensão (variação laranja) */
.cta-prot{border-left-color:var(--orange)}
.cta-prot:hover{border-color:var(--orange)}
.cta-prot .cta-eyebrow{color:var(--orange)}
.cta-prot .cta-btn{background:var(--orange);color:#fff}
`;
